printf 'RUNNER=1\nharness=claude\nmodel=sonnet\n' > "$rdcol10_run_dir/run.env"
rdcol10_pod_dir="$(newdir)"; tmpdirs+=("$rdcol10_pod_dir")
printf '{"cost_usd":1e1000,"total_cost_usd":0.25}' > "$rdcol10_pod_dir/summary.json"
