    --branch fs-k8s-test-rdcol10 --run-dir "$rdcol10_run_dir" "$proj_dir"; then
    ok "collect of a run with a non-finite pod cost_usd exits 0"
else
    no "collect of a run with a non-finite pod cost_usd exits 0" "$(cat "$rdcol10_out")"
fi
